        List<int> tau, List<int> lam, List<int> pi) {
  // Find common height
  int h;
  if (beta[x] <= beta[y]) {
    h = lam[beta[y] & -beta[x]];
  } else {
    h = lam[beta[x] & -beta[y]];
  }

  // Find true height
  int k = alfa[x] & alfa[y] & -(1 << h);
  h = lam[k & -k];

  // Find beta[z]
